1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:flutter_localizations/flutter_localizations.dart';
5	import 'package:fpdart/fpdart.dart' hide State;
6	import 'package:go_router/go_router.dart';
7	
8	import 'core/di/injection_container.dart';
9	import 'core/failure/failure.dart';
10	import 'core/navigation/app_router.dart';
11	import 'core/navigation/expiry_overlay_host.dart';
12	import 'features/account/domain/repositories/account_settings_repository.dart';
13	import 'features/auth/domain/repositories/session_repository.dart';
14	import 'features/vault/domain/repositories/vault_repository.dart';
15	
16	Future<void> main() async {
17	  WidgetsFlutterBinding.ensureInitialized();
18	  try {
19	    await setupCoreDependencies();
20	  } catch (error) {
21	    debugPrint(
22	      'Cerne failed to start: could not load .env ($error). Copy '
23	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
24	      'SUPABASE_ANON_KEY before running the app.',
25	    );
26	    rethrow;
27	  }
28	  // Review finding: `app_router.dart`'s `_redirect` composes the vault
29	  // gate (AD-14) strictly first, synchronously, ahead of everything else —
30	  // it routes to `/vault` on the very first redirect evaluation, before
31	  // `CerneApp`'s own fire-and-forget boot fetch below could ever resolve.
32	  // `/vault`'s builder reads `currentBiometricEnabled` synchronously at
33	  // that moment, so without this awaited (bounded) fetch here, every cold
34	  // start reads the untouched default (`true`) regardless of what the user
35	  // actually set — not the "one-time, benign gap on a slow-network cold
36	  // boot" it looked like. Bounded so a hung network call can't delay app
37	  // launch indefinitely; on timeout/failure, `currentBiometricEnabled` is
38	  // simply left at its documented default, same outcome as before this
39	  // fix.
40	  await sl<AccountSettingsRepository>()
41	      .fetchBiometricEnabled()
42	      .timeout(const Duration(seconds: 2), onTimeout: () => right(unit))
43	      .catchError(_asUnchangedPreference);
44	  runApp(const CerneApp());
45	}
46	
47	// `catchError`'s handler must still complete the Future with a value of
48	// its declared type (`Either<Failure, Unit>`) — a `void`-returning handler
49	// would try to complete it with `null`, which isn't assignable to that
50	// non-nullable type and would itself throw. Top-level (not a
51	// `_CerneAppState` method) so both `main()`'s own awaited fetch above and
52	// `CerneApp.initState`'s fire-and-forget one below can share it.
53	Either<Failure, Unit> _asUnchangedPreference(
54	  Object error,
55	  StackTrace stackTrace,
56	) {
57	  debugPrint('Cerne: fetchBiometricEnabled() threw unexpectedly ($error)');
58	  return left(Failure.malformedResponse(message: error.toString()));
59	}
